@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=334  cases=10
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:setProjectTracks, reaper:addItem, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's scope default and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 55-76
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 88-95

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 99-107
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 110-119
  @case 'focusState before any render returns both bits false'  [harness]  @ 122-129
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 135-148
  @case 'newTakeBelow + duplicateUnpooledBelow mint a parked slot on scratch and select it'  [harness]  @ 152-173
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 177-200
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 206-249
  @case 'empty grid shows the single no-takes message'  [harness]  @ 255-269
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 276-308
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 312-332

